def natural_sort_strings(strings):
    """Sort strings by natural order: digit runs compared as integers,
    non-digit runs compared case-sensitively by Unicode code point.
    Text tokens sort before numeric tokens when kinds differ.
    Shorter equal-prefix token lists sort first; equal keys preserve input order.
    Empty strings allowed; Unicode digits are treated as text."""
    import re

    def _key(s):
        if s == "":
            return ([], 0)
        tokens = re.findall(r'\d+|\D+', s)
        parts = []
        has_digit = False
        for tok in tokens:
            if tok.isdigit():
