import re

def natural_sort_strings(items):
    """
    Pure Python natural sort of a list of strings.
    Split strings into maximal ASCII-digit and non-digit runs.
    Compare digit runs by integer value, non-digit runs by case-sensitive Unicode lexical order;
    text tokens sort before numeric tokens when kinds differ.
    Shorter equal-prefix token lists sort first; equal keys preserve input order.
    Empty strings allowed; Unicode digits are text.
    """
    _token_re = re.compile(r'(\d+|\D+)')

    def _key(s):
        if not s:
            return ([], True)
        tokens = _token_re.findall(s)
        key_parts = []
        for tok in tokens:
            if tok.isascii() and tok.isdigit():
                key_parts.append((0, int(tok)))
            else:
                key_parts.append((1, tok))
        has_digit = any(tok.isascii() and tok.isdigit() for tok in tokens)
        has_non_digit = any(not (tok.isascii() and tok.isdigit()) for tok in tokens)
        kind = 0 if has_digit and not has_non_digit else 1 if has_non_digit and not has_digit else 2
        return (key_parts, kind)

    return sorted(items, key=_key)
