def natural_sort_strings(items):
    def _key(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('digit', int(s[i:j])))
                i = j
            else:
                j = i
                while j < n and not s[j].isdigit():
                    j += 1
                tokens.append(('text', s[i:j]))
                i = j
        return tokens

    @functools.cmp_to_key
    def _compare(a, b):
        ka = _key(a)
        kb = _key(b)
        min_len = min(len(ka), len(kb))
        for i in range(min_len):
            ta, ka_ = ka[i]
            tb, kb_ = kb[i]
            if ta != tb:
                return -1 if ta == 'text' else 1
            if ta == 'digit':
                if ka_ < kb_:
                    return -1
                elif ka_ > kb_:
                    return 1
            else:
                if ka_ < kb_:
                    return -1
                elif ka_ > kb_:
                    return 1
        if len(ka) != len(kb):
            return -1 if len(ka) < len(kb) else 1
        return 0

    return sorted(items, key=functools.cmp_to_key(_compare))

def natural_sort_strings(strings):
    """Sort strings in natural order.

    Splits each string into maximal ASCII-digit and non-digit runs.
    Digit runs are compared by integer value; non-digit runs by
    case-sensitive Unicode lexical order.
    Text tokens sort before numeric tokens when kinds differ.
    Shorter equal-prefix token lists sort first; equal keys preserve
    input order. Empty strings are allowed; Unicode digits are treated
    as text.

    Args:
        strings: list of str to sort.

    Returns:
        list of str sorted in natural order.
    """
    def _key(s):
        if s == "":
            return ([], True)
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isdigit() and ord(s[i]) < 128:
                j = i
                while j < len(s) and s[j].isdigit() and ord(s[j]) < 128:
                    j += 1
                tokens.append(("num", int(s[i:j])))
                i = j
            else:
                j = i
                while j < len(s) and not (s[j].isdigit() and ord(s[j]) < 128):
                    j += 1
                tokens.append(("text", s[i:j]))
                i = j
        has_num = any(t[0] == "num" for t in tokens)
        return (tokens, has_num)

    return sorted(strings, key=_key)

